import random

def run_node_code(items):
    users = []
    for item in items:
      user_data = {
              'id': item.json.get('tg_id', ''),
              'chat_id': item.json.get('tg_id', ''),
              'info': item.json.get('info', ''),
              'lastPairedWith': item.json.get('Last_paired_with', None),
          }
      users.append(user_data)

    random.shuffle(users)

    pairs = []
    unpaired_users = list(users)
    while len(unpaired_users) >= 2:
        user1 = unpaired_users.pop(0)

        user2_index = -1
        for i, u2 in enumerate(unpaired_users):
            if u2['id'] != user1['lastPairedWith']:
                user2_index = i
                break

        if user2_index != -1:
            user2 = unpaired_users.pop(user2_index)
            pairs.append([user1, user2])
        elif len(unpaired_users) > 0:
            user2 = unpaired_users.pop(0)
            pairs.append([user1, user2])
        else:
            pass

    output_items = []
    for pair in pairs:
        output_items.append({
            'json': {
                'user1': pair[0],
                'user2': pair[1]
            }
        })

    if not output_items:
        output_items.append({'json': {}})
    return output_items


# print(_input.all())

